    foreach ($programs as $id) $wpdb->delete(Atlas_Events::table('programs'),['id'=>$id]);foreach ($offers as $id) { $wpdb->delete(DB::table('inventory'),['offer_id'=>$id]);wp_delete_post($id,true); }foreach ($users as $id) { $wpdb->delete(Atlas_Events::table('scan_keys'),['actor_id'=>$id]);wp_delete_user($id); }wp_set_current_user(0);
}
